const FRAMES_PER_SECOND = 60; // frames per second

let initialAngle = 30; // initial angle of the pendulum in degrees
let angularVelocity = 0; // initial angular velocity of the pendulum in radians/second

document.getElementById('start-button').addEventListener('click', startPendulum);

function startPendulum() {
  initialAngle = parseInt(document.getElementById('initial-angle').value);
  angularVelocity = 0;
  drawPendulum();
  animatePendulum();
}

function drawPendulum() {
