  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(canvas.width / 2, canvas.height / 2);
  ctx.lineTo(canvas.width / 2 + PENDULUM_LENGTH * Math.sin(Math.radians(initialAngle)), canvas.height / 2 - PENDULUM_LENGTH * Math.cos(Math.radians(initialAngle)));
  ctx.closePath();
  ctx.fill();
}

function animatePendulum() {
